cd /app/w && python3 -c "
import json,collections
meds=json.load(open('meds.json'))
rows=json.load(open('clinicmr.json'))
EVAL='2026-09-24'
cur=collections.defaultdict(list)
for r in rows:
    p=r['subject']['reference'][-36:]
    nm=meds.get(r['medicationReference']['reference'].split('/')[-1])
    end=r.get('dispenseRequest',{}).get('validityPeriod',{}).get('end','')[:10]
    if r['status']=='completed' and end>=EVAL:
        cur[p].append((nm,r['dosageInstruction'][0]['text'],r['authoredOn'][:10],r['id']))
AC={'Warfarin','Apixaban','Rivaroxaban','Dabigatran Etexilate','Edoxaban','Enoxaparin Sodium','Heparin'}
QT={'Citalopram','Escitalopram Oxalate','Haloperidol','Methadone','Amiodarone','Sotalol','Dofetilide','Sotalol HCl','Haloperidol Lactate'}
for p,l in sorted(cur.items()):
    names=set(x[0] for x in l)
    tag=''
    if names&AC: tag+=' AC:'+','.join(sorted(names&AC))
    if names&QT: tag+=' QT:'+','.join(sorted(names&QT))
    print(p, '|', ', '.join(sorted(n or '?' for n in names)), '|', tag)
